 "content": "def transform(grid):
    """Recolor complete horizontal/vertical lines of the separator color."""
    h, w = len(grid), len(grid[0])
    full_rows = [r for r in range(h) if all(v == grid[r][0] for v in grid[r])]
    if not full_rows:
        return [row[:] for row in grid]
    color = grid[full_rows[0]][0]
    rows = {r for r in full_rows if grid[r][0] == color}
    cols = {c for c in range(w) if all(grid[r][c] == color for r in range(h))}
    out = [row[:] for row in grid]
    for r in rows:
        for c in range(w):
            out[r][c] = 2
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out
